package lcdrill

import "sort"

// countDistinctInRanges answers each query [l, r] (inclusive, 0-indexed) with
// the number of distinct values in nums[l..r].
func countDistinctInRanges(nums []int, queries [][2]int) []int {
	n, q := len(nums), len(queries)
	out := make([]int, q)
	if n == 0 || q == 0 {
		return out
	}

	// Block width sqrt(n) balances the two pointer costs: the left pointer
	// moves at most one block per query, the right at most n per block.
	block := 1
	for block*block < n {
		block++
	}

	order := make([]int, q)
	for i := range order {
		order[i] = i
	}
	sort.Slice(order, func(a, b int) bool {
		x, y := queries[order[a]], queries[order[b]]
		bx, by := x[0]/block, y[0]/block
		if bx != by {
			return bx < by
		}
		// Snake the right pointer: within an odd block it sweeps back down,
		// which halves its total travel.
		if bx%2 == 1 {
			return x[1] > y[1]
		}
		return x[1] < y[1]
	})

	maxV := 0
	for _, v := range nums {
		if v > maxV {
			maxV = v
		}
	}
	count := make([]int32, maxV+1)

	cur := 0
	add := func(i int) {
		if count[nums[i]] == 0 {
			cur++
		}
		count[nums[i]]++
	}
	remove := func(i int) {
		count[nums[i]]--
		if count[nums[i]] == 0 {
			cur--
		}
	}

	l, r := 0, -1
	for _, qi := range order {
		ql, qr := queries[qi][0], queries[qi][1]
		for r < qr {
			r++
			add(r)
		}
		for l > ql {
			l--
			add(l)
		}
		for r > qr {
			remove(r)
			r--
		}
		for l < ql {
			remove(l)
			l++
		}
		out[qi] = cur
	}
	return out
}
