func TestMaxBipartiteMatchingExamples(t *testing.T) {
	// Left 0 and 1 both only reach right 0, so one of them stays unmatched.
	if got := maxBipartiteMatching(2, 2, [][]int{{0}, {0}}); got != 1 {
		t.Fatalf("shared neighbour = %d, want 1", got)
	}
