package lcdrill

import "math/rand"

// reservoirSample returns k values drawn uniformly without replacement from the
// stream that next yields, reading the stream once and holding at most k values.
func reservoirSample(next func() (int, bool), k int, r *rand.Rand) []int {
	if k <= 0 {
		return nil
	}
	res := make([]int, 0, k)
	seen := 0
	for {
		v, ok := next()
		if !ok {
			break
		}
		seen++
		if len(res) < k {
			res = append(res, v)
			continue
		}
		// The i-th element (1-indexed) belongs in the reservoir with
		// probability k/i; landing outside [0, k) is the decision to skip it.
		if j := r.Intn(seen); j < k {
			res[j] = v
		}
	}
	return res
}
