package lcdrill

import "math/rand"

func reservoirSample(next func() (int, bool), k int, r *rand.Rand) []int {
	var all []int
	for {
		v, ok := next()
		if !ok {
			break
		}
		all = append(all, v)
	}
	if k > len(all) {
		k = len(all)
	}
	p := r.Perm(len(all))
	out := make([]int, k)
	for i := 0; i < k; i++ {
		out[i] = all[p[i]]
	}
	return out
}
